  pp_b200_r5_c1: "デバイスのネットワークアドレス。アクセスの日時。要求されたリソースのアドレス",
  pp_b200_r5_c2: "取扱事業者の正当な利益",
  pp_b200_r5_c3: "最後のアクセスの日から7暦日以内",
  pp_b200_r6_c0: "領収書の作成と収入の記録",
  pp_b200_r6_c1: "電子メールアドレス。支払いに関する情報",
  pp_b200_r6_c2: "法令の要件",
  pp_b200_r6_c3: "法令に定められた期間",
  pp_b200_r7_c0: "情報提供および広告メッセージの送信",
  pp_b200_r7_c1: "電子メールアドレス",
